<template>
  <el-form
    :model="ruleForm"
    :rules="rules"
    ref="ruleForm"
    label-width="130px"
    class="demo-ruleForm mt-30"
    size="small"
  >
    <el-form-item label="状态" prop="is_record">
      <el-switch
        v-model="ruleForm.status"
        :active-value="1"
        :inactive-value="0"
      ></el-switch>
    </el-form-item>
    <el-form-item label="ip规则" prop="info">
      <el-input
        type="textarea"
        v-model="ruleForm.info"
        :autosize="{ minRows: 6, maxRows: 18 }"
        style="width: 80%"
      ></el-input>
      <div>
        通配符用 * 表示，如192.168.0.* 多个ip请以<span
          style="font-size: 18px; font-weight: bold"
        >
          , </span
        >分割
      </div>
    </el-form-item>
    <el-form-item>
      <el-button type="primary" @click="submitForm('ruleForm')"
        >确 定</el-button
      >
    </el-form-item>
  </el-form>
</template>

<script>
export default {
  data() {
    return {
      ruleForm: {},
      rules: {
        info: [{ required: true, message: "请输入", trigger: "blur" }],
      },
    };
  },
  created() {
    this.getData();
  },
  methods: {
    getData() {
      this.$api.get(`/sys/getAccessRules`).then((res) => {
        this.ruleForm = { ...res.data.data, info: res.data.data.info.join() };
      });
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          let data = {
            ...this.ruleForm,
            info: this.ruleForm.info.split(","),
          };
          this.$api.post("/sys/saveAccessRules", data).then(() => {
            this.$message.success("操作成功");
            this.addVisible = false;
            this.getData();
          });
        }
      });
    },
  },
};
</script>

